import Badge from "@/components/UI/Badge";
import { FormationWithDetails } from "@/types/formationDetails";
import Image from "next/image";
import SessionsSection from "./SessionsSection";
import { Clock, Award } from "lucide-react";

interface HeroSectionProps {
  formation: FormationWithDetails;
}

export default function HeroSection({ formation }: HeroSectionProps) {
  const getDurationDisplay = () => {
    if (formation.durationHours) {
      return `${formation.durationHours}h`;
    }
    if (formation.durationDays) {
      return `${formation.durationDays} jour${formation.durationDays > 1 ? "s" : ""}`;
    }
    return null;
  };

  return (
    <section className="pt-40 md:pt-48 pb-16 md:pb-24 px-10 md:px-[40px] lg:px-[120px] relative overflow-hidden">
      {/* Background gradient */}
      <div className="absolute inset-0 -z-10">
        <div className="absolute top-0 left-1/4 w-96 h-96 bg-primary/5 rounded-full blur-3xl" />
        <div className="absolute bottom-0 right-1/4 w-80 h-80 bg-primary/10 rounded-full blur-3xl" />
      </div>

      <div className="flex flex-col lg:flex-row gap-8 lg:gap-12 items-start">
        {/* Partie gauche - Informations de la formation */}
        <div className="flex-1 lg:flex-[1.2]">
          <Badge className="mb-4">{formation.category.name}</Badge>

          <h1 className="text-[28px] md:text-[40px] lg:text-[48px] tracking-[-1px] md:tracking-[-2px] text-darkBlue font-sora font-bold leading-tight mb-4">
            {formation.title}
          </h1>

          {/* Stats badges */}
          <div className="flex flex-wrap gap-3 mb-6">
            {getDurationDisplay() && (
              <div className="inline-flex items-center gap-2 px-4 py-2 bg-white rounded-full border border-gray-200 shadow-sm">
                <Clock className="w-4 h-4 text-primary" />
                <span className="font-satoshi text-sm font-medium text-darkBlue">
                  {getDurationDisplay()}
                </span>
              </div>
            )}
            {formation.successRate && (
              <div className="inline-flex items-center gap-2 px-4 py-2 bg-white rounded-full border border-gray-200 shadow-sm">
                <Award className="w-4 h-4 text-primary" />
                <span className="font-satoshi text-sm font-medium text-darkBlue">
                  {formation.successRate}% de réussite
                </span>
              </div>
            )}
          </div>

          {formation.longDescription && (
            <p className="text-base md:text-lg text-grayBlue font-satoshi leading-relaxed mb-6 max-w-2xl">
              {formation.longDescription}
            </p>
          )}

          {/* Image de la formation */}
          {formation.imageUrl && (
            <div className="relative w-full h-56 md:h-72 rounded-3xl overflow-hidden border border-gray-200 shadow-sm">
              <Image
                src={formation.imageUrl}
                alt={formation.title}
                fill
                className="object-cover"
                priority
              />
              {/* Overlay gradient */}
              <div className="absolute inset-0 bg-gradient-to-t from-darkBlue/20 to-transparent" />
            </div>
          )}
        </div>

        {/* Partie droite - Sessions disponibles */}
        <div className="w-full lg:w-auto lg:min-w-[380px] lg:max-w-[420px] lg:sticky lg:top-32">
          <SessionsSection
            formationId={formation.id}
            formationTitle={formation.title}
            categoryName={formation.category?.name}
          />
        </div>
      </div>
    </section>
  );
}
